14	/**
15	 * 曝光预占单数据访问。加锁/CAS 方法必须在事务内调用。
16	 */
17	@Repository
18	public class ReservationRepository {
19	
20	    private final JdbcTemplate jdbc;
21	
22	    public ReservationRepository(JdbcTemplate jdbc) {
23	        this.jdbc = jdbc;
24	    }
25	
26	    private static final RowMapper<Reservation> MAPPER = (rs, rowNum) -> new Reservation(
27	            rs.getString("reservation_id"),
28	            rs.getString("campaign_id"),
29	            rs.getString("visitor_id"),
30	            rs.getDate("utc_date"),
31	            ReservationStatus.valueOf(rs.getString("status")),
32	            rs.getLong("created_at_utc"),
33	            rs.getLong("expires_at_utc"),
34	            (Long) rs.getObject("terminal_at_utc"));
35	
36	    private static final String COLUMNS =
37	            "reservation_id, campaign_id, visitor_id, utc_date, status, "
38	                    + "created_at_utc, expires_at_utc, terminal_at_utc";
39	
40	    public void insert(Reservation reservation) {
41	        jdbc.update("INSERT INTO exposure_reservation (" + COLUMNS + ") VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
42	                reservation.reservationId(),
43	                reservation.campaignId(),
44	                reservation.visitorId(),
45	                reservation.utcDate(),
46	                reservation.status().name(),
47	                reservation.createdAtUtc(),
48	                reservation.expiresAtUtc(),
49	                reservation.terminalAtUtc());
50	    }
51	
52	    public Optional<Reservation> findById(String reservationId) {
53	        List<Reservation> list = jdbc.query(
54	                "SELECT " + COLUMNS + " FROM exposure_reservation WHERE reservation_id = ?",
55	                MAPPER, reservationId);
56	        return list.stream().findFirst();
57	    }
58	
59	    /**
60	     * 行锁读取预占单。
61	     */
62	    public Optional<Reservation> lockById(String reservationId) {
63	        List<Reservation> list = jdbc.query(
64	                "SELECT " + COLUMNS + " FROM exposure_reservation WHERE reservation_id = ? FOR UPDATE",
65	                MAPPER, reservationId);
66	        return list.stream().findFirst();
67	    }
68	
69	    /**
70	     * 行锁查询某公告下已到期（now &gt;= expires_at_utc）但仍为 RESERVED 的预占单。
71	     */
72	    public List<Reservation> lockExpiredReserved(String campaignId, long nowUtc) {
73	        return jdbc.query("SELECT " + COLUMNS + " FROM exposure_reservation "
74	                        + "WHERE campaign_id = ? AND status = 'RESERVED' AND expires_at_utc <= ? FOR UPDATE",
75	                MAPPER, campaignId, nowUtc);
76	    }
77	
78	    /**
79	     * 条件 CAS：仅当当前状态为 expect 时改为 target 并记录终态时刻。
80	     *
81	     * @return 是否更新成功（并发终态竞争时只有一个返回 true）
82	     */
83	    public boolean compareAndSetStatus(String reservationId, ReservationStatus expect,
84	                                       ReservationStatus target, long terminalAtUtc) {
85	        int rows = jdbc.update("UPDATE exposure_reservation SET status = ?, terminal_at_utc = ? "
