            mockMvc.perform(get("/api/exposure/campaigns/c1/decision").param("visitorId", "v1"))
                    .andExpect(status().isOk())
                    .andExpect(jsonPath("$.reason").value("CONSENT_DENIED"));
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }
}

