/**
 * 预占指纹的稳定业务部分：活动版本、访客、类别、时刻依据与频控字段。
 * “时刻”为首次裁决时刻，由 {@link #runIdempotent} 在插入幂等记录时附加并固化，
 * 因此跨毫秒的同键重放仍返回最初裁决，而不是误判为异参。
 */
private String applyFingerprint(String campaignId, String visitorId) {
    Campaign campaign = requireCampaign(campaignId);
    return "APPLY|" + campaign.campaignId() + "|v" + campaign.version() + "|"
            + visitorId + "|cat=" + normalize(campaign.category())
            + "|cap=" + campaign.dailyTotalCap()
            + "|vcap=" + campaign.perVisitorDailyCap();
}

